```typescript
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { vi, describe, it, expect, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock contexts - I aten't having with testing implementation details
const mockCart = {
  items: [{ id: '1', name: 'Pointy Hat', price: 29.99 }],
  total: 29.99,
  clearCart: vi.fn(),
};
const mockProcessPayment = vi.fn();

vi.mock('./CartContext', () => ({
  useCart: () => mockCart,
}));
vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment }),
}));

describe('Checkout - And I DO mean thorough', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockCart.items = [{ id: '1', name: 'Pointy Hat', price: 29.99 }];
  });

  describe('Happy Path - Though nothing in life is truly happy', () => {
    it('completes full checkout flow like a proper witch doing proper magic', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      mockProcessPayment.mockResolvedValue({ orderId: 'ORD-123' });

      render(<Checkout onComplete={onComplete} />);

      // Shipping - no grays, only facts
      await user.type(screen.getByLabelText(/street address/i), '1 Lancre');
      await user.type(screen.getByLabelText(/city/i), 'Lancre Town');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip/i), '12345');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Esmerelda Weatherwax');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review and submit
      expect(screen.getByText(/pointy hat/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
      expect(onComplete).toHaveBeenCalledWith('ORD-123');
    });
  });

  describe('Validation - Sin is when you treat code like it doesnt matter', () => {
    it('shows error for empty street', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/street address is required/i);
    });

    it('rejects invalid ZIP like I reject foolishness', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip/i), 'WRONG');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  describe('Empty Cart - I dont hold with this', () => {
    it('shows empty cart message', () => {
      mockCart.items = [];
      render(<Checkout />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });

  describe('Accessibility - PROPER accessibility', () => {
    it('has no violations', async () => {
      const { container } = render(<Checkout />);
      expect(await axe(container)).toHaveNoViolations();
    });
  });
});
```

There. Tests that see what's REALLY happening. Not what you THINK is happening.
